#include "kernel/codecapps/audio/selftest.h"

#include "kernel/codecapps/arena.h"
#include "kernel/codecapps/audio/aiff.h"
#include "kernel/codecapps/audio/midi.h"
#include "kernel/codecapps/audio/mod.h"
#include "kernel/codecapps/image/apng.h"
#include "kernel/codecapps/registry.h"
#include "kernel/codecapps/selftest_w2_blobs.h"
#include "kernel/codecapps/woff.h"
#include "kernel/serial.hpp"

// CodecsApps wave-2 selftest: MIDI synth, MOD/XM tracker playback,
// APNG animation, AIFF decode, WOFF unwrap. Fixtures are embedded byte
// vectors generated by tools/mkwave2_selftest.py.
// Serial markers:
//   aiff decode=ok           midi notes=N dur=Nms   midi render=ok
//   mod chans=N rows=N       mod render=ok          xm chans=N rows=N
//   xm render=ok             apng frames=N          apng anim=ok
//   woff tables=N            woff decode=ok         codec w2=ok

namespace hype::codec {

    namespace {

        constexpr hcpp::size_t w2_pages = 512;  // 2 MiB of PMM scratch

        bool bytes_equal(const hcpp::u8 *a, const hcpp::u8 *b,
                         hcpp::size_t n) noexcept {
            for (hcpp::size_t i = 0; i < n; ++i)
                if (a[i] != b[i]) return false;
            return true;
        }

        bool pcm_nonzero(const PcmBuf &buf) noexcept {
            if (buf.data == nullptr || buf.frames == 0) return false;
            const auto *pcm = reinterpret_cast<const hcpp::i16 *>(buf.data);
            for (hcpp::size_t i = 0; i < buf.frames * buf.format.channels; ++i)
                if (pcm[i] != 0) return true;
            return false;
        }

        bool test_aiff(Arena &arena) noexcept {
            using namespace w2blobs;
            if (codec_probe(clip_aiff, sizeof(clip_aiff)) != CodecId::Aiff)
                return false;
            PcmBuf buf{};
            const bool ok =
                codec_decode(CodecId::Aiff, clip_aiff, sizeof(clip_aiff), &buf,
                             arena) == CodecStatus::Ok &&
                buf.frames == 32 && buf.format.channels == 1 &&
                buf.format.sample_rate == 8000 &&
                buf.format.sample_format == audio::AudioSampleFormat::S16Le &&
                pcm_nonzero(buf);
            serial::write("aiff decode=");
            serial::write_line(ok ? "ok" : "fail");
            return ok;
        }

        bool test_midi(Arena &arena) noexcept {
            using namespace w2blobs;
            if (codec_probe(clip_mid, sizeof(clip_mid)) != CodecId::Midi)
                return false;
            MidiInfo info{};
            if (!midi_inspect(clip_mid, sizeof(clip_mid), arena, info))
                return false;
            serial::write("midi notes=");
            serial::write_dec32(info.notes);
            serial::write(" dur=");
            serial::write_dec32(info.duration_ms);
            serial::write("ms\r\n");
            if (info.notes != 4 || info.events == 0 || info.duration_ms == 0)
                return false;
            PcmBuf buf{};
            const bool ok =
                codec_decode(CodecId::Midi, clip_mid, sizeof(clip_mid), &buf,
                             arena) == CodecStatus::Ok &&
                buf.frames > 2205 && buf.format.channels == 2 &&
                buf.format.sample_rate == midi_render_rate && pcm_nonzero(buf);
            serial::write("midi render=");
            serial::write_line(ok ? "ok" : "fail");
            return ok;
        }

        bool test_mod(Arena &arena) noexcept {
            using namespace w2blobs;
            if (codec_probe(clip_mod, sizeof(clip_mod)) != CodecId::Mod)
                return false;
            ModInfo info{};
            if (!mod_inspect(clip_mod, sizeof(clip_mod), arena, info))
                return false;
            serial::write("mod chans=");
            serial::write_dec32(info.channels);
            serial::write(" rows=");
            serial::write_dec32(info.rows);
            serial::write("\r\n");
            if (info.channels != 4 || info.rows != 64 || info.patterns != 1 ||
                info.instruments != 1)
                return false;
            PcmBuf buf{};
            const bool ok =
                codec_decode(CodecId::Mod, clip_mod, sizeof(clip_mod), &buf,
                             arena) == CodecStatus::Ok &&
                buf.frames > 22050 && buf.format.channels == 2 &&
                pcm_nonzero(buf);
            serial::write("mod render=");
            serial::write_line(ok ? "ok" : "fail");
            return ok;
        }

        bool test_xm(Arena &arena) noexcept {
            using namespace w2blobs;
            if (codec_probe(clip_xm, sizeof(clip_xm)) != CodecId::Xm)
                return false;
            XmInfo info{};
            if (!xm_inspect(clip_xm, sizeof(clip_xm), arena, info))
                return false;
            serial::write("xm chans=");
            serial::write_dec32(info.channels);
            serial::write(" rows=");
            serial::write_dec32(info.rows_total);
            serial::write(" inst=");
            serial::write_dec32(info.instruments);
            serial::write("\r\n");
            if (info.channels != 2 || info.instruments != 1 ||
                !info.has_samples)
                return false;
            PcmBuf buf{};
            const bool ok =
                codec_decode(CodecId::Xm, clip_xm, sizeof(clip_xm), &buf,
                             arena) == CodecStatus::Ok &&
                buf.frames != 0 && buf.format.channels == 2 &&
                pcm_nonzero(buf);
            serial::write("xm render=");
            serial::write_line(ok ? "ok" : "fail");
            return ok;
        }

        bool test_apng(Arena &arena) noexcept {
            using namespace w2blobs;
            if (codec_probe(clip_apng, sizeof(clip_apng)) != CodecId::Apng)
                return false;
            const hcpp::u32 declared =
                image::apng_frame_count(clip_apng, sizeof(clip_apng));
            serial::write("apng frames=");
            serial::write_dec32(declared);
            serial::write("\r\n");
            if (declared != 2) return false;
            image::ApngAnim anim;
            if (!image::apng_anim_open(anim, clip_apng, sizeof(clip_apng)))
                return false;
            FrameBuf canvas{};
            hcpp::u16 delay = 0;
            if (!image::apng_anim_next(anim, canvas, delay, arena)) return false;
            // Frame 0: solid red, full canvas.
            if (canvas.width != 4 || canvas.height != 4 || delay != 100)
                return false;
            if (canvas.data[0] != 255 || canvas.data[1] != 0 ||
                canvas.data[2] != 0 || canvas.data[3] != 255)
                return false;
            // Frame 1: OVER-blended semi-blue at (1,1).
            if (!image::apng_anim_next(anim, canvas, delay, arena)) return false;
            const hcpp::u8 *px =
                canvas.data + static_cast<hcpp::size_t>(canvas.pitch) + 4;
            // over(128-alpha blue, red): r = 0 + 255*(1-128/255) ~= 127
            const bool ok = px[0] >= 120 && px[0] <= 135 && px[2] == 255 &&
                            px[3] == 255;
            serial::write("apng anim=");
            serial::write_line(ok ? "ok" : "fail");
            return ok;
        }

        bool test_woff(Arena &arena) noexcept {
            using namespace w2blobs;
            if (codec_probe(clip_woff, sizeof(clip_woff)) != CodecId::Woff)
                return false;
            archive::BlobOut out{};
            const bool ok =
                woff_decode(clip_woff, sizeof(clip_woff), &out, arena) ==
                    CodecStatus::Ok &&
                out.size == sizeof(clip_sfnt) &&
                bytes_equal(out.data, clip_sfnt, out.size);
            serial::write("woff tables=2 decode=");
            serial::write_line(ok ? "ok" : "fail");
            return ok;
        }

    }  // namespace

    bool codec_wave2_selftest() noexcept {
        Arena arena{};
        if (!arena_from_pmm(arena, w2_pages)) {
            serial::write_line("codec w2=nomem");
            return false;
        }
        bool ok = true;
        arena_reset(arena);
        ok = test_aiff(arena) && ok;
        arena_reset(arena);
        ok = test_midi(arena) && ok;
        arena_reset(arena);
        ok = test_mod(arena) && ok;
        arena_reset(arena);
        ok = test_xm(arena) && ok;
        arena_reset(arena);
        ok = test_apng(arena) && ok;
        arena_reset(arena);
        ok = test_woff(arena) && ok;
        arena_release_pmm(arena, w2_pages);
        serial::write("codec w2=");
        serial::write_line(ok ? "ok" : "fail");
        return ok;
    }

}  // namespace hype::codec
